import React from 'react';
import { useApp } from '../context/AppContext';

const ROLE_COLORS = {
  manager: 'bg-purple-900 border-purple-500 text-purple-300',
  waiter: 'bg-blue-900 border-blue-500 text-blue-300',
  chef: 'bg-amber-900 border-amber-500 text-amber-300',
  cashier: 'bg-emerald-900 border-emerald-500 text-emerald-300',
};

export default function StaffView() {
  const { staff } = useApp();

  return (
    <div>
      <h2 className="text-2xl font-bold text-white mb-6">Staff Management</h2>
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
        {staff.map((member) => (
          <div key={member.id} className={`rounded-xl border-2 p-5 ${ROLE_COLORS[member.role] || ROLE_COLORS.waiter}`}>
            <div className="flex justify-between items-start mb-3">
              <div>
                <p className="text-xl font-bold text-white">{member.name}</p>
                <p className="text-sm capitalize">{member.role}</p>
              </div>
              <span className="text-xs font-mono text-gray-500">{member.id}</span>
            </div>
            <div className="mt-3 space-y-1">
              {Object.entries(member.permissions || {}).map(([perm, allowed]) => (
                <div key={perm} className="flex items-center gap-2 text-sm">
                  <span className={allowed ? 'text-emerald-400' : 'text-gray-600'}>
                    {allowed ? '✓' : '✗'}
                  </span>
                  <span className={allowed ? 'text-gray-200' : 'text-gray-600'}>
                    {perm.replace(/([A-Z])/g, ' $1').trim()}
                  </span>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
